/**
 * ApprovalSync — SLA Escalation Event Entity
 * Milestone: BE-08
 *
 * Persists durable, idempotent escalation records generated by warning threshold
 * detection, statutory target breaches, and severe overdue escalation sweeps.
 */

import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  ManyToOne,
  JoinColumn,
  Index,
} from 'typeorm';
import { ApplicationStatus, SlaTier, UserRole } from '../../shared/contracts';
import { Application } from '../../database/entities/application.entity';
import { SlaTimer } from '../../database/entities/sla-timer.entity';
import { SlaEscalationLevel } from '../enums/sla-escalation-level.enum';

@Entity('sla_escalations')
export class SlaEscalation {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Index('idx_sla_escalations_timer_id')
  @Column({ name: 'timer_id', type: 'uuid' })
  timerId: string;

  @ManyToOne(() => SlaTimer, { onDelete: 'RESTRICT' })
  @JoinColumn({ name: 'timer_id' })
  timer: SlaTimer;

  @Index('idx_sla_escalations_app_id')
  @Column({ name: 'application_id', type: 'uuid' })
  applicationId: string;

  @ManyToOne(() => Application, { onDelete: 'RESTRICT' })
  @JoinColumn({ name: 'application_id' })
  application: Application;

  @Column({
    type: 'enum',
    enum: ApplicationStatus,
    enumName: 'application_status_enum',
  })
  stage: ApplicationStatus;

  @Column({
    type: 'enum',
    enum: SlaTier,
    enumName: 'sla_tier_enum',
  })
  tier: SlaTier;

  @Column({
    name: 'escalation_level',
    type: 'varchar',
    length: 32,
  })
  escalationLevel: SlaEscalationLevel;

  /**
   * Unique idempotency key preventing duplicate escalation emissions
   * Format: sla-esc:<timerId>:<tier>:<level>
   */
  @Index('uq_sla_escalations_idempotency_key', { unique: true })
  @Column({ name: 'idempotency_key', type: 'varchar', length: 191 })
  idempotencyKey: string;

  @Column({
    name: 'target_role',
    type: 'enum',
    enum: UserRole,
    enumName: 'user_role_enum',
  })
  targetRole: UserRole;

  @Column({ name: 'policy_id', type: 'varchar', length: 64 })
  policyId: string;

  @Column({
    name: 'policy_version',
    type: 'varchar',
    length: 32,
    default: '1.0.0',
  })
  policyVersion: string;

  @Column({ name: 'target_deadline', type: 'timestamptz' })
  targetDeadline: Date;

  @Column({
    name: 'detected_at',
    type: 'timestamptz',
    default: () => 'CURRENT_TIMESTAMP',
  })
  detectedAt: Date;

  @Column({
    name: 'recipient_details_jsonb',
    type: 'jsonb',
    default: () => "'{}'::jsonb",
  })
  recipientDetailsJsonb: Record<string, unknown>;

  @Column({ name: 'is_dispatched', type: 'boolean', default: true })
  isDispatched: boolean;

  @Index('idx_sla_escalations_created_at')
  @CreateDateColumn({ name: 'created_at', type: 'timestamptz' })
  createdAt: Date;
}
